<script setup lang="ts">
import {reactive,ref} from 'vue'
import {KeyRound,ShieldCheck} from 'lucide-vue-next'
import {errorMessage} from '@shtong/web-shared'
const props=defineProps<{phase:string;error?:string;onLogin:(login:string,password:string)=>Promise<void>;onPassword:(current:string,next:string)=>Promise<void>;onLogout:()=>Promise<void>}>()
const login=reactive({name:'',password:''}),pass=reactive({current:'',next:'',confirm:''}),busy=ref(false),localError=ref('')
async function run(action:()=>Promise<void>){if(busy.value)return;busy.value=true;localError.value='';try{await action()}catch(error){localError.value=errorMessage(error)}finally{busy.value=false}}
function change(){if(pass.next!==pass.confirm){localError.value='两次输入的新密码不一致';return}if(pass.next.length<8||pass.next.length>128||!/[A-Z]/.test(pass.next)||!/[a-z]/.test(pass.next)||!/\d/.test(pass.next)){localError.value='密码至少 8 位，并同时包含大写字母、小写字母和数字';return}void run(()=>props.onPassword(pass.current,pass.next))}
</script>
<template><main v-if="props.phase==='checking'" class="gate" aria-live="polite"><div class="loader"/><p>正在检查登录状态</p></main><main v-else-if="props.phase==='anonymous'" class="login-page"><section class="login-brand"><span class="brand-mark">生</span><p class="overline light">学校账户管理</p><h1>生化通</h1><p>系统管理员登录</p><div class="login-assurance"><ShieldCheck :size="22" aria-hidden="true"/><span>使用账号和密码登录</span></div></section><form class="login-form" @submit.prevent="run(()=>props.onLogin(login.name,login.password))"><p class="overline">系统管理</p><h2>登录管理系统</h2><label>登录账号<input v-model="login.name" autocomplete="username" maxlength="100" required></label><label>密码<input v-model="login.password" type="password" autocomplete="current-password" maxlength="128" required></label><p v-if="localError||props.error" class="error" role="alert">{{localError||props.error}}</p><button class="primary" :disabled="busy">{{busy?'正在验证':'登录'}}</button></form></main><main v-else-if="props.phase==='password'" class="gate"><form class="gate-dialog" @submit.prevent="change"><KeyRound :size="28" aria-hidden="true"/><p class="overline">账户安全</p><h1>设置正式密码</h1><p>密码至少 8 位，并同时包含大写字母、小写字母和数字。</p><label>临时密码<input v-model="pass.current" type="password" autocomplete="current-password" maxlength="128" required></label><label>新密码<input v-model="pass.next" type="password" autocomplete="new-password" minlength="8" maxlength="128" required></label><label>确认新密码<input v-model="pass.confirm" type="password" autocomplete="new-password" minlength="8" maxlength="128" required></label><p v-if="localError||props.error" class="error" role="alert">{{localError||props.error}}</p><button class="primary" :disabled="busy">更新密码</button><button type="button" class="text-button" @click="run(props.onLogout)">退出</button></form></main></template>
